@push('scripts')<script>
document.querySelectorAll('form[action$="/card-brands"]').forEach(form=>{const type=form.querySelector('[name=type]');function refresh(){form.querySelectorAll('[name^="rates["]').forEach(input=>{const disabled=type.value==='debit'&&input.name!=='rates[1]';input.disabled=disabled;input.closest('.field').hidden=disabled;});}type.addEventListener('change',refresh);refresh();});
</script>@endpush
